<template>
  <h1>招生日曆</h1><form class="panel filters" @submit.prevent="load"><label>入學學年<input v-model.number="year" type="number" min="2000" max="2100" required /></label><label>學段<select v-model="level"><option value="KG">幼稚園</option><option value="PRIMARY">小學</option><option value="SECONDARY">中學</option></select></label><button>查看核實事件</button></form>
  <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="loading" role="status">正在讀取…</p>
  <section class="panel"><h2>公開核實事件</h2><p>只有同一入學學年、已審核及已發佈的事件才會出現。不將去年截止日期移到今年。</p><p v-if="!events.length" class="empty">當屆尚未有已核實的招生事件；這不代表所有學校尚未接受申請。</p><article v-for="event in events" :key="event.id"><h3>{{ event.title }}</h3><p>{{ event.starts_on??event.starts_at }} · {{ event.route }}</p><a :href="event.source_url" target="_blank" rel="noopener noreferrer">核對官方安排</a></article><button :disabled="!events.length" @click="exportOfficial">匯出已核實事件 ICS</button></section>
  <section class="panel"><h2>私人事件（只在此瀏覽器）</h2><p>例如你自行收到的面試日期。這些記錄不是平台核實的官方公告。</p><form class="filters" @submit.prevent="add"><label>事件名稱<input v-model="title" maxlength="200" required /></label><label>日期<input v-model="date" type="date" required /></label><button :disabled="!privateReady">新增私人事件</button></form><article v-for="event in privateState.data.events" :key="event.id"><p><span class="badge">私人</span>{{ event.date }} · {{ event.title }} <button class="secondary" @click="remove(event.id)">刪除</button></p></article><p>私人事件會隨「私人清單」的 JSON 備份一同匯出；不混入官方 ICS。</p></section>
</template>
<script setup lang="ts">
import { ref, onMounted } from 'vue';import { z } from 'zod';import { AdmissionEvent, PersonalEvent, PrivateExport, type PublicEvent } from '@hk-school/contracts/domain';import { toCalendar } from '@hk-school/contracts/calendar';import { getData } from '../lib/api';import { loadPrivate, savePrivate, downloadText, type PrivateSnapshot } from '../lib/private-store';
const year=ref(new Date().getFullYear()+1);const level=ref('PRIMARY');const events=ref<PublicEvent[]>([]);const loading=ref(false);const error=ref('');const title=ref('');const date=ref('');const privateReady=ref(false);const privateState=ref<PrivateSnapshot>({revision:0,data:{schema_version:1,entries:[],events:[]}});
async function load(){loading.value=true;error.value='';events.value=[];try{events.value=(await getData(`/api/v1/events?level=${level.value}&year=${year.value}`,z.array(AdmissionEvent))).data;}catch(e){error.value=String(e);}finally{loading.value=false;}}
onMounted(async()=>{void load();try{privateState.value=await loadPrivate();privateReady.value=true;}catch(e){error.value=String(e);}});
async function add(){try{const event=PersonalEvent.parse({id:crypto.randomUUID(),title:title.value,date:date.value,note:''});const data=PrivateExport.parse(privateState.value.data);data.events.push(event);privateState.value=await savePrivate(data,privateState.value.revision);title.value='';date.value='';}catch(e){error.value=String(e);}}
async function remove(id:string){try{const data={...privateState.value.data,events:privateState.value.data.events.filter(event=>event.id!==id)};privateState.value=await savePrivate(data,privateState.value.revision);}catch(e){error.value=String(e);}}
function exportOfficial(){downloadText('school-verified-events.ics',toCalendar(events.value),'text/calendar; charset=utf-8');}
</script>
